legend:
  // tile RAM offset T + the art tile; bits 12-14 pick the palette: 0 sky, 1 ground, 2 coin, 3 hazard, 4 brick, 5 flag
  . = T + gfx_sky
  [ = T + gfx_cloud_l
  ] = T + gfx_cloud_r
  = = (T + gfx_grass) | (1 << 12)
  # = (T + gfx_dirt) | (1 << 12)
  B = (T + gfx_brick) | (4 << 12)
  o = (T + gfx_coin) | (2 << 12)
  ^ = (T + gfx_spikes) | (3 << 12)
  G = (T + gfx_flag) | (5 << 12)
  | = (T + gfx_pole) | (1 << 12)
  P = T + gfx_sky, marker
  E = T + gfx_sky, marker
